from functools import lru_cache


class Solution:
    def getMaxGridHappiness(self, m: int, n: int, introvertsCount: int, extrovertsCount: int) -> int:
        GAIN = (0, -30, 20)

        @lru_cache(maxsize=None)
        def dfs(idx, prev, cur, intro, extro):
            if intro + extro == 0 or idx == m * n:
                return 0
            r, c = divmod(idx, n)
            p = 3 ** c
            up = prev // p % 3
            left = cur % 3 if c else 0
            last = c == n - 1
            if last:
                best = dfs(idx + 1, cur * 3, 0, intro, extro)
            else:
                best = dfs(idx + 1, prev, cur * 3, intro, extro)
            if intro:
                add = 120
                if up:
                    add += GAIN[1] + GAIN[up]
                if left:
                    add += GAIN[1] + GAIN[left]
                nxt = (dfs(idx + 1, cur * 3 + 1, 0, intro - 1, extro) if last
                       else dfs(idx + 1, prev, cur * 3 + 1, intro - 1, extro))
                best = max(best, add + nxt)
            if extro:
                add = 40
                if up:
                    add += GAIN[2] + GAIN[up]
                if left:
                    add += GAIN[2] + GAIN[left]
                nxt = (dfs(idx + 1, cur * 3 + 2, 0, intro, extro - 1) if last
                       else dfs(idx + 1, prev, cur * 3 + 2, intro, extro - 1))
                best = max(best, add + nxt)
            return best

        return dfs(0, 0, 0, introvertsCount, extrovertsCount)

