class Solution {
    private int total, width;
    private final Map<Integer, Integer> memo = new HashMap<>();
    private static final int[] GAIN = {0, -30, 20};

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        total = m * n;
        width = n;
        memo.clear();
        return dfs(0, 0, 0, introvertsCount, extrovertsCount);
    }

    private int dfs(int idx, int prev, int cur, int intro, int extro) {
        if (intro + extro == 0 || idx == total) return 0;
        int key = ((idx * 243 + prev) * 243 + cur) * 49 + intro * 7 + extro;
        Integer cached = memo.get(key);
        if (cached != null) return cached;
        int c = idx % width, p = 1;
        for (int i = 0; i < c; i++) p *= 3;
        int up = prev / p % 3;
        int left = c > 0 ? cur % 3 : 0;
        boolean last = c == width - 1;
        int nidx = idx + 1;
        int best = last ? dfs(nidx, cur * 3, 0, intro, extro)
                        : dfs(nidx, prev, cur * 3, intro, extro);
        if (intro > 0) {
            int add = 120;
            if (up > 0) add += GAIN[1] + GAIN[up];
            if (left > 0) add += GAIN[1] + GAIN[left];
            int nxt = last ? dfs(nidx, cur * 3 + 1, 0, intro - 1, extro)
                           : dfs(nidx, prev, cur * 3 + 1, intro - 1, extro);
            best = Math.max(best, add + nxt);
        }
        if (extro > 0) {
            int add = 40;
            if (up > 0) add += GAIN[2] + GAIN[up];
            if (left > 0) add += GAIN[2] + GAIN[left];
            int nxt = last ? dfs(nidx, cur * 3 + 2, 0, intro, extro - 1)
                           : dfs(nidx, prev, cur * 3 + 2, intro, extro - 1);
            best = Math.max(best, add + nxt);
        }
        memo.put(key, best);
        return best;
    }
}

