class Solution:
    def getMaxGridHappiness(self, m: int, n: int, introvertsCount: int, extrovertsCount: int) -> int:
        total = m * n
        sz = 3 ** n
        p = sz // 3
        neg = float("-inf")
        dp = [[[neg] * 7 for _ in range(7)] for _ in range(sz)]
        dp[0][introvertsCount][extrovertsCount] = 0
        for i in range(total):
            c = i % n
            ndp = [[[neg] * 7 for _ in range(7)] for _ in range(sz)]
            for mask in range(sz):
                up = mask // p
                left = mask % 3 if c else 0
                sbase = (mask % p) * 3
                for inn in range(7):
                    for ex in range(7):
                        v = dp[mask][inn][ex]
                        if v == neg:
                            continue
                        if v > ndp[sbase][inn][ex]:
                            ndp[sbase][inn][ex] = v
                        if inn:
                            pen = (60 if up == 1 else 10 if up == 2 else 0) + \
                                  (60 if left == 1 else 10 if left == 2 else 0)
                            nv = v + 120 - pen
                            if nv > ndp[sbase + 1][inn - 1][ex]:
                                ndp[sbase + 1][inn - 1][ex] = nv
                        if ex:
                            bonus = (40 if up == 2 else -10 if up == 1 else 0) + \
                                    (40 if left == 2 else -10 if left == 1 else 0)
                            nv = v + 40 + bonus
                            if nv > ndp[sbase + 2][inn][ex - 1]:
                                ndp[sbase + 2][inn][ex - 1] = nv
            dp = ndp
        return max(v for layer in dp for row in layer for v in row)

