        int total = m * n;
        int sz = 1;
        for (int i = 0; i < n; i++) sz *= 3;
        int p = sz / 3;
        const int NEG = INT_MIN / 2;
        vector<vector<vector<int>>> dp(sz, vector<vector<int>>(7, vector<int>(7, NEG)));
        dp[0][introvertsCount][extrovertsCount] = 0;
        for (int i = 0; i < total; i++) {
            int c = i % n;
            vector<vector<vector<int>>> ndp(sz, vector<vector<int>>(7, vector<int>(7, NEG)));
            for (int mask = 0; mask < sz; mask++) {
                int up = mask / p;
                int left = c ? mask % 3 : 0;
                int sbase = (mask % p) * 3;
                for (int inn = 0; inn <= 6; inn++) for (int ex = 0; ex <= 6; ex++) {
                    int v = dp[mask][inn][ex];
                    if (v == NEG) continue;
                    if (v > ndp[sbase][inn][ex]) ndp[sbase][inn][ex] = v;
                    if (inn) {
                        int pen = (up == 1 ? 60 : up == 2 ? 10 : 0) + (left == 1 ? 60 : left == 2 ? 10 : 0);
                        int nv = v + 120 - pen;
                        if (nv > ndp[sbase + 1][inn - 1][ex]) ndp[sbase + 1][inn - 1][ex] = nv;
                    }
                    if (ex) {
                        int bon = (up == 2 ? 40 : up == 1 ? -10 : 0) + (left == 2 ? 40 : left == 1 ? -10 : 0);
                        int nv = v + 40 + bon;
                        if (nv > ndp[sbase + 2][inn][ex - 1]) ndp[sbase + 2][inn][ex - 1] = nv;
                    }
